/**
 * Calculate due date based on payment terms.
 * @param {string} issueDate - Date in YYYY-MM-DD format
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string} - Due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    // Last day of the month
    const [year, month] = issueDate.split('-').map(Number);
    const nextMonth = new Date(Date.UTC(year, month, 1)); // 1st of next month
    nextMonth.setUTCDate(0); // Go back to last day of current month
    const lastDay = String(nextMonth.getUTCDate()).padStart(2, '0');
    return `${year}-${String(month).padStart(2, '0')}-${lastDay}`;
  }
  return null;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate issueDate
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate and calculate due date
  if (!['NET14', 'NET30', 'EOM'].includes(terms)) {
    return fail('TERMS_INVALID');
  }
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate lines
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and build invoice lines
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discountPercent: explicit value wins, otherwise use tier discount
    let discountPercent;
    if (line.discountPercent !== undefined) {
      discountPercent = line.discountPercent;
    } else {
      discountPercent = TIER_DISCOUNTS[customer.tier];
    }

    // Validate discountPercent
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product info
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
    terms,
    dueDate,
  });
}

